//! Internal helpers used by the code generated by `#[derive(AssetCollection)]`.

use std::any::TypeId;

use bevy_asset::{Asset, AssetPath, AssetServer, Handle, UntypedHandle};
use bevy_platform::collections::HashMap;

pub use crate::typed_folder::{get_folder_as, load_folder_as};

/// A collection field type that holds handles of a single asset type.
pub trait TypedHandleField {
    /// The asset type behind the field's handles.
    type Asset: Asset;
}

impl<A: Asset> TypedHandleField for Handle<A> {
    type Asset = A;
}

impl<T: TypedHandleField> TypedHandleField for Option<T> {
    type Asset = T::Asset;
}

impl<A: Asset> TypedHandleField for Vec<Handle<A>> {
    type Asset = A;
}

impl<K, A: Asset, S> TypedHandleField for HashMap<K, Handle<A>, S> {
    type Asset = A;
}

/// Load `path` as the asset type of the field that `field` points to.
pub fn load_as_field<'a, C, F: TypedHandleField>(
    _field: fn(&C) -> &F,
    asset_server: &AssetServer,
    path: impl Into<AssetPath<'a>>,
) -> UntypedHandle {
    asset_server.load::<F::Asset>(path).untyped()
}

/// The asset type of the field that `field` points to.
pub fn asset_type_of_field<C, F: TypedHandleField>(_field: fn(&C) -> &F) -> TypeId {
    TypeId::of::<F::Asset>()
}
